
-- INSERT IMAGES FOR 0-5MONTHS SKILLS
do $$

declare
    content_id integer;
    content_type_field_image_id integer;
begin

select "Id" into content_type_field_image_id from "ContentTypeField" where "ContentTypeId" = 7 and "FieldName" = 'SupportImage';

-- Does { childFirstName } grasp onto a small object (e.g., your finger, a spoon) when put in his/her hand?
select cv."ContentId" into content_id
from "ContentValue" cv 
inner join "ContentTypeField" ctf on cv."ContentTypeFieldId" = ctf."Id" 
where ctf."ContentTypeId" = 7 and ctf."FieldName" = 'name' and cv."Value" = 'Does [childFirstName] grasp onto a small object (e.g., your finger, a spoon) when put in his/her hand?';

INSERT INTO public."ContentValue" ("ContentId", "LocaleId", "ContentTypeFieldId", "Value", "StatusId", "TenantId", "InsertedDate", "UpdatedDate")
VALUES(content_id, '9688cd08-adef-408c-9d34-5d75ae5c44df', content_type_field_image_id, 'data:image/png;base64,', null, null, CURRENT_DATE, CURRENT_DATE);  

-- When lying on his/her stomach, can { childFirstName } hold his/her head and chest off the ground using only his/her hands and arms for support?
select cv."ContentId" into content_id
from "ContentValue" cv 
inner join "ContentTypeField" ctf on cv."ContentTypeFieldId" = ctf."Id" 
where ctf."ContentTypeId" = 7 and ctf."FieldName" = 'name' and cv."Value" = 'When lying on his/her stomach, can [childFirstName] hold his/her head and chest off the ground using only his/her hands and arms for support?';

INSERT INTO public."ContentValue" ("ContentId", "LocaleId", "ContentTypeFieldId", "Value", "StatusId", "TenantId", "InsertedDate", "UpdatedDate")
VALUES(content_id, '9688cd08-adef-408c-9d34-5d75ae5c44df', content_type_field_image_id, 'data:image/png;base64,', null, null, CURRENT_DATE, CURRENT_DATE);  

-- Can { childFirstName } pick up a small object (e.g., a small toy or small stone) using just one hand?
